{
  "themes": [
    {
      "cluster": 12,
      "name": "Pre-Order Dispatch Delays",
      "description": "Customers report that pre-ordered books are not dispatched or delivered on the expected release date, often resulting in stock unavailability."
    },
    {
      "cluster": 13,
      "name": "Unanswered Direct Messages",
      "description": "Users complain about sending direct messages for support or inquiries that receive no response or acknowledgment from the brand."
    },
    {
      "cluster": 14,
      "name": "Diwali Holiday Delivery Failures",
      "description": "Customers express frustration over packages not arriving during the Diwali holiday period, citing logistics failures and missed delivery windows."
    },
    {
      "cluster": 15,
      "name": "Order Status and Cancellation Issues",
      "description": "Users seek updates on specific order IDs or report issues with cancelling orders and unexplained cancellations by the platform."
    },
    {
      "cluster": 16,
      "name": "Poor Customer Service Quality",
      "description": "Customers describe the support experience as worst, pathetic, or unhelpful, citing unresponsive staff and lack of resolution for delivery or product issues."
    },
    {
      "cluster": 17,
      "name": "Incorrect Pricing and MRP Discrepancies",
      "description": "Users report mismatches between displayed prices, MRP, and final charges, including confusion over savings calculations and flash sale pricing."
    },
    {
      "cluster": 18,
      "name": "Account Security and Hacking Concerns",
      "description": "Customers report suspicious activity, hacked accounts, or phishing emails impersonating the brand, seeking assistance with security breaches."
    },
    {
      "cluster": 19,
      "name": "Account Lockout and Login Failures",
      "description": "Users are unable to log in or sign up due to locked accounts, password reset failures, or broken sign-up pages without clear notification."
    },
    {
      "cluster": 20,
      "name": "Invalid Review Notifications",
      "description": "Customers receive automated thank-you emails for reviews they did not write or encounter issues with product warranty and review integrity."
    },
    {
      "cluster": 21,
      "name": "Amazon India Service Negligence",
      "description": "Users in India complain about aggressive or useless customer service, missing items, and a general lack of accountability from the local team."
    },
    {
      "cluster": 22,
      "name": "Website Functionality and Link Errors",
      "description": "Customers report broken links, site errors, or inability to perform basic actions like adding balance or selecting product sizes."
    },
    {
      "cluster": 23,
      "name": "Lost Packages and Shipping Delays",
      "description": "Users report packages being lost, left in unsafe locations, or significantly delayed beyond promised shipping times like two-day delivery."
    }
  ]
}
